//! Raw `no_std` bindings to the Cortex-A53 AMP (`standalone_a53_amp`) standalone BSP (every header in
//! `platform/psu_cortexa53_1/standalone_a53_amp/bsp/include`), used by `hello_world_a53_1` (A53#1) and `hello_world_a53_2` (A53#2). Generated by
//! bindgen at build time. Linking this crate pulls in libxil, libxilstandalone and
//! libxiltimer (plus newlib's libc and libgcc) as one link group.
//!
//! `static inline` functions (`Xil_Out32`, ...) and the function-like macros in
//! `xil-bsp-build/c/xilrs_shim.c` (`XTtcPs_Start`, `XWdtPs_RestartWdt`, `dmb`, ...)
//! are callable under their C names through small C shims compiled alongside the bindings.
#![no_std]
#![allow(non_upper_case_globals, non_camel_case_types, non_snake_case)]
#![allow(clippy::all, rustdoc::all, unnecessary_transmutes)]
// bindgen's flexible-array helper (__IncompleteArrayField) predates edition 2024
#![allow(unsafe_op_in_unsafe_fn)]

// Empty when built for the other core's target (see xil-bsp-build), e.g. by
// rust-analyzer, which checks the whole workspace for one target
include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
